import importlib.util,json,pathlib
s=importlib.util.spec_from_file_location('helper','work/nucbox-tls-20261021/root-activate-reviewed.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
# A new diskless, disconnected, NEVER STARTED VM. Exact GUID ownership gates cleanup.
p=r'''[Console]::OutputEncoding=[Text.UTF8Encoding]::new();$name='enclave-resource-api-canary-20261023-1614';$id=$null;$o=[ordered]@{at=(Get-Date).ToUniversalTime().ToString('o');name=$name;started=$false};try {if(Get-VM -Name $name -EA SilentlyContinue){throw 'name already exists'};$v=New-VM -Name $name -Generation 2 -MemoryStartupBytes 512MB -NoVHD;$id=$v.Id;Set-VMProcessor -VM $v -Count 4 -Maximum 84;$p=Get-VMProcessor -VM $v;$o.whole=[ordered]@{count=$p.Count;maximum=$p.Maximum;state=(Get-VM -Id $id).State.ToString()};$ns='root/virtualization/v2';$vm=Get-CimInstance -Namespace $ns -ClassName Msvm_ComputerSystem -Filter ('Name="'+$id.Guid+'"');$vssd=$vm|Get-CimAssociatedInstance -ResultClassName Msvm_VirtualSystemSettingData|Where-Object {$_.VirtualSystemType -eq 'Microsoft:Hyper-V:System:Realized'};$cpu=$vssd|Get-CimAssociatedInstance -ResultClassName Msvm_ProcessorSettingData;$o.before=[ordered]@{quantity=$cpu.VirtualQuantity;limit=$cpu.Limit;units=$cpu.AllocationUnits};$o.ok=($p.Count -eq 4 -and $p.Maximum -eq 84 -and $cpu.Limit -eq 84000 -and (Get-VM -Id $id).State -eq 'Off')}catch{$o.ok=$false;$o.error=$_.Exception.Message}finally{if($id){$v=Get-VM -Id $id -EA SilentlyContinue;if($v -and $v.Name -eq $name -and $v.State -eq 'Off'){Remove-VM -VM $v -Force;$o.removed= -not [bool](Get-VM -Id $id -EA SilentlyContinue)}else{$o.cleanupRefused=$true}}};$o|ConvertTo-Json -Depth 6 -Compress'''
r=m.ps(p,40);pathlib.Path('work/coupled-resource-shares-20261023/root-validation/cpu-api-canary.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r));raise SystemExit(0 if r.get('ok') and r.get('removed') else 1)
